import { assertHashType, SUPPORTED_PBKDF2 } from './utils/assertHash.mjs'
import { assertEmptyRest, assertInteger } from './utils/assertUint8.mjs'
import { fromUint8orString } from './utils/input.mjs'
import { assertOutputFormat, fromUint8Super } from './utils/output.mjs'
import crypto from 'node:crypto'
import util from 'node:util'

if (!crypto.webcrypto) throw new Error('Unexpected crypto-browserify or old Node.js crypto')

const pbkdf2node = util.promisify(crypto.pbkdf2)

export async function pbkdf2(type, password, salt, { iterations, dkLen, ...w }, format = 'uint8') {
  assertEmptyRest(w)
  assertHashType(type, SUPPORTED_PBKDF2)
  assertOutputFormat(format) // Early check, this is rechecked later in fromUint8Super

  assertInteger(iterations, 'iterations', 1)
  assertInteger(dkLen, 'dkLen', 1)

  password = fromUint8orString(password, 'password') // eslint-disable-line no-param-reassign
  salt = fromUint8orString(salt, 'salt') // eslint-disable-line no-param-reassign
  if (!(salt.length > 0)) throw new Error('Zero-length salt is not supported')

  return fromUint8Super(await pbkdf2node(password, salt, iterations, dkLen, type), format)
}
